//! ClassicalSyriac inflection, learned from Wiktionary.
//!
//! Generated by morphe from the Kaikki ClassicalSyriac dump of 2026-10-03. Do not edit.
//! Every function is total: unknown words are inflected by prediction, and
//! the `_scored` versions give every candidate with a confidence, best first.
//! Variant confidences reflect Wiktionary's listing order, not measured usage.
//!
//! Data: Wiktionary contributors, CC BY-SA 4.0, via kaikki.org.

#![forbid(unsafe_code)]

pub use morphe::{Options, Scored};
use std::sync::OnceLock;

static DATA: &[u8] = include_bytes!("model.bin");

/// The trained model, for dynamic queries.
pub fn model() -> Option<&'static morphe::Model> {
    static MODEL: OnceLock<Option<morphe::Model>> = OnceLock::new();
    MODEL.get_or_init(|| morphe::Model::decode(DATA)).as_ref()
}

fn best(scored: Scored<String>, word: &str) -> String {
    scored.into_iter().next().map_or_else(|| word.split(',').next().unwrap_or(word).trim().to_string(), |x| x.0)
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum State {
    Absolute,
    Construct,
    Emphatic,
}

impl State {
    pub const ALL: [Self; 3] = [Self::Absolute, Self::Construct, Self::Emphatic];
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum Number {
    Singular,
    Plural,
}

impl Number {
    pub const ALL: [Self; 2] = [Self::Singular, Self::Plural];
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum Gender {
    Masculine,
    Feminine,
}

impl Gender {
    pub const ALL: [Self; 2] = [Self::Masculine, Self::Feminine];
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum Possessor {
    FirstSingular,
    SecondMasculineSingular,
    SecondFeminineSingular,
    ThirdMasculineSingular,
    ThirdFeminineSingular,
    FirstPlural,
    SecondMasculinePlural,
    SecondFemininePlural,
    ThirdMasculinePlural,
    ThirdFemininePlural,
}

impl Possessor {
    pub const ALL: [Self; 10] = [Self::FirstSingular, Self::SecondMasculineSingular, Self::SecondFeminineSingular, Self::ThirdMasculineSingular, Self::ThirdFeminineSingular, Self::FirstPlural, Self::SecondMasculinePlural, Self::SecondFemininePlural, Self::ThirdMasculinePlural, Self::ThirdFemininePlural];
}

/// Settings for systematic choices. `ClassicalSyriac::default()` is what the free functions use.
#[derive(Clone, Copy, Debug, Default)]
pub struct ClassicalSyriac {
    pub options: Options,
}

impl ClassicalSyriac {
    /// Keep stress and similar marks in the output (on by default).
    pub fn marks(mut self, on: bool) -> Self {
        self.options.marks = on;
        self
    }

    /// A noun form.
    pub fn noun_scored(&self, word: &str, state: State, number: Number) -> Scored<String> {
        let cell: Option<u32> = match (state, number,) {
            (State::Absolute, Number::Singular,) => Some(0),
            (State::Absolute, Number::Plural,) => Some(1),
            (State::Construct, Number::Singular,) => Some(2),
            (State::Construct, Number::Plural,) => Some(3),
            (State::Emphatic, Number::Singular,) => Some(4),
            (State::Emphatic, Number::Plural,) => Some(5),
        };
        match (model(), cell) {
            (Some(m), Some(c)) => m.inflect(0, c, word, self.options),
            _ => Vec::new(),
        }
    }

    /// A noun form. The best candidate; the word itself if nothing is known.
    pub fn noun(&self, word: &str, state: State, number: Number) -> String {
        best(self.noun_scored(word, state, number), word)
    }

    /// A noun form (possessed).
    pub fn noun_possessed_scored(&self, word: &str, possessor: Possessor) -> Scored<String> {
        let cell: Option<u32> = match (possessor,) {
            (Possessor::FirstSingular,) => Some(6),
            (Possessor::SecondMasculineSingular,) => Some(7),
            (Possessor::SecondFeminineSingular,) => Some(8),
            (Possessor::ThirdMasculineSingular,) => Some(9),
            (Possessor::ThirdFeminineSingular,) => Some(10),
            (Possessor::FirstPlural,) => Some(11),
            (Possessor::SecondMasculinePlural,) => Some(12),
            (Possessor::SecondFemininePlural,) => Some(13),
            (Possessor::ThirdMasculinePlural,) => Some(14),
            (Possessor::ThirdFemininePlural,) => Some(15),
        };
        match (model(), cell) {
            (Some(m), Some(c)) => m.inflect(0, c, word, self.options),
            _ => Vec::new(),
        }
    }

    /// A noun form (possessed). The best candidate; the word itself if nothing is known.
    pub fn noun_possessed(&self, word: &str, possessor: Possessor) -> String {
        best(self.noun_possessed_scored(word, possessor), word)
    }

    /// Scored gender of a noun.
    pub fn noun_gender(&self, word: &str) -> Scored<Gender> {
        model().map(|m| m.inherent(0, 0, word).into_iter().filter_map(|(v, p)| Some((Gender::ALL.get(v as usize).copied()?, p))).collect()).unwrap_or_default()
    }

    /// Dictionary spelling of a noun (with stress marks where the data has them).
    pub fn noun_lemma(&self, word: &str) -> String {
        model().and_then(|m| m.lemma(0, word)).unwrap_or_else(|| word.to_string())
    }

    /// A adj form.
    pub fn adj_scored(&self, word: &str, state: State, gender: Gender, number: Number) -> Scored<String> {
        let cell: Option<u32> = match (state, gender, number,) {
            (State::Absolute, Gender::Masculine, Number::Singular,) => Some(0),
            (State::Absolute, Gender::Masculine, Number::Plural,) => Some(1),
            (State::Absolute, Gender::Feminine, Number::Singular,) => Some(2),
            (State::Absolute, Gender::Feminine, Number::Plural,) => Some(3),
            (State::Construct, Gender::Masculine, Number::Singular,) => Some(4),
            (State::Construct, Gender::Masculine, Number::Plural,) => Some(5),
            (State::Construct, Gender::Feminine, Number::Singular,) => Some(6),
            (State::Construct, Gender::Feminine, Number::Plural,) => Some(7),
            (State::Emphatic, Gender::Masculine, Number::Singular,) => Some(8),
            (State::Emphatic, Gender::Masculine, Number::Plural,) => Some(9),
            (State::Emphatic, Gender::Feminine, Number::Singular,) => Some(10),
            (State::Emphatic, Gender::Feminine, Number::Plural,) => Some(11),
        };
        match (model(), cell) {
            (Some(m), Some(c)) => m.inflect(1, c, word, self.options),
            _ => Vec::new(),
        }
    }

    /// A adj form. The best candidate; the word itself if nothing is known.
    pub fn adj(&self, word: &str, state: State, gender: Gender, number: Number) -> String {
        best(self.adj_scored(word, state, gender, number), word)
    }

    /// Dictionary spelling of a adj (with stress marks where the data has them).
    pub fn adj_lemma(&self, word: &str) -> String {
        model().and_then(|m| m.lemma(1, word)).unwrap_or_else(|| word.to_string())
    }

}

